/**
 * Replace all CN generated drafts with LaTeX-aware generated set
 * + image/code drafts. Year = "generated by 10tracker.com" (not topic).
 * solution left empty (no GateOverflow); detail lives in solutiontext.
 *
 * node --env-file=.env.local scripts/regenerate-cn-drafts.mjs
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { randomUUID } from 'crypto';
import { createClient } from '@supabase/supabase-js';
import {
  buildGeneratedQuestions,
  toRestInsertRow,
} from '../src/lib/question-gen/generateExamQuestions.js';
import { GENERATED_YEAR_LABEL } from '../src/lib/question-gen/cnTemplates.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
const supabase = createClient(url, key);

async function collectIds(queryBuilder) {
  const { data, error } = await queryBuilder;
  if (error) throw error;
  return (data || []).map((r) => r._id);
}

// 1) Delete ONLY unpublished drafts — never touch published rows
//    (do NOT delete by year alone; that would wipe live generated questions)
const ids = await collectIds(
  supabase
    .from('examtracker')
    .select('_id')
    .eq('subject', 'computer-networks')
    .eq('verification_status', 'unpublished_draft')
);
console.log('deleting unpublished CN drafts only', ids.length);
for (let i = 0; i < ids.length; i += 100) {
  const chunk = ids.slice(i, i + 100);
  const { error } = await supabase.from('examtracker').delete().in('_id', chunk);
  if (error) throw error;
}

// 2) Insert template batch
const { rows, errors } = buildGeneratedQuestions({
  countsByDifficulty: { easy: 5, medium: 5, hard: 5 },
});
if (errors.length) {
  console.error(errors);
  process.exit(1);
}
const payload = rows.map(toRestInsertRow);
let inserted = 0;
for (let i = 0; i < payload.length; i += 50) {
  const chunk = payload.slice(i, i + 50);
  const { data, error } = await supabase.from('examtracker').insert(chunk).select('_id');
  if (error) {
    console.error(error.message);
    process.exit(1);
  }
  inserted += data.length;
}
console.log('inserted template drafts', inserted);

// 3) Upload diagrams + image/code drafts
const bucket = 'mcq-images';
const diagramDir = path.join(__dirname, 'cn-diagrams');
async function uploadSvg(filename) {
  const bytes = fs.readFileSync(path.join(diagramDir, filename));
  const objectPath = `gate-cn/drafts/${Date.now()}-${filename}`;
  const { error } = await supabase.storage.from(bucket).upload(objectPath, bytes, {
    contentType: 'image/svg+xml',
    upsert: true,
  });
  if (error) throw new Error(error.message);
  return supabase.storage.from(bucket).getPublicUrl(objectPath).data.publicUrl;
}

const uTopo = await uploadSvg('topology-forwarding.svg');
const uFrag = await uploadSvg('fragmentation-path.svg');
const uSlide = await uploadSvg('sliding-window-link.svg');
const uLan = await uploadSvg('lan-switch.svg');

function row(partial) {
  return {
    _id: randomUUID(),
    category: 'GATE-CSE',
    subject: 'computer-networks',
    verification_status: 'unpublished_draft',
    year: GENERATED_YEAR_LABEL,
    options_A: partial.options_A ?? '',
    options_B: partial.options_B ?? '',
    options_C: partial.options_C ?? '',
    options_D: partial.options_D ?? '',
    questionCode: partial.questionCode ?? null,
    ...partial,
  };
}

const imageQs = [
  row({
    chapter: 'network-layer-protocol',
    topic: 'IPv4 CIDR fragmentation NAT',
    difficulty: 'medium',
    questionImage: uTopo,
    question: `<p>Host A sends an IP packet to Host B. Using longest-prefix match on R1's table in the figure, which outgoing interface is used?</p><p><img alt="topology" src="${uTopo}" /></p>`,
    options_A: 'eth0',
    options_B: 'eth1',
    options_C: 'Both eth0 and eth1',
    options_D: 'Packet is dropped (no match)',
    correct_option: 'B',
    solution: '',
    solutiontext:
      '<p><strong>Step 1:</strong> Destination $10.1.2.9$ is covered by $10.1.2.0/24$, $10.1.0.0/16$, and the default route.</p><p><strong>Step 2:</strong> Longest-prefix match picks the most specific entry: $/24$.</p><p><strong>Step 3:</strong> That route points to eth1.</p><p><strong>Answer:</strong> Option B (eth1).</p>',
  }),
  row({
    chapter: 'network-layer-protocol',
    topic: 'IPv4 CIDR fragmentation NAT',
    difficulty: 'hard',
    questionImage: uFrag,
    question: `<p>A sender transmits an IPv4 datagram with a <strong>$3000$-byte payload</strong> (IP header $20$ bytes, $\\mathrm{DF}=0$) over the path in the figure. After crossing both links, how many fragments arrive at the receiver?</p><p><img alt="fragmentation" src="${uFrag}" /></p>`,
    correct_option: '5',
    solution: '',
    solutiontext:
      '<p><strong>Link 1 (MTU $1500$):</strong> max payload $\\left\\lfloor(1500-20)/8\\right\\rfloor\\times 8 = 1480$ bytes $\\Rightarrow$ $\\left\\lceil 3000/1480 \\right\\rceil = 3$ fragments.</p><p><strong>Link 2 (MTU $820$):</strong> max payload $800$ bytes. The three fragments split as $2+2+1 = 5$.</p><p><strong>Answer:</strong> $5$ fragments arrive.</p>',
  }),
  row({
    chapter: 'physical-layer',
    topic: 'Switching and performance metrics',
    difficulty: 'medium',
    questionImage: uSlide,
    question: `<p>For the link in the figure, ignore processing delay and ACK transmission time. The minimum sender window size (in frames) for continuous transmission (utilization $\\to 100\\%$) is ____.</p><p><img alt="link" src="${uSlide}" /></p>`,
    correct_option: '41',
    solution: '',
    solutiontext:
      '<p><strong>Step 1:</strong> $T_t = 1000/10^6 = 1\\ \\mathrm{ms}$, $2T_p = 40\\ \\mathrm{ms}$.</p><p><strong>Step 2:</strong> For full utilization, $W \\ge \\left\\lceil (T_t+2T_p)/T_t \\right\\rceil = 41$.</p><p><strong>Answer:</strong> $41$ frames.</p>',
  }),
  row({
    chapter: 'data-link-layer',
    topic: 'Error detection and MAC',
    difficulty: 'easy',
    questionImage: uLan,
    question: `<p>In the switched Ethernet LAN shown, H1 sends a unicast frame to H4. Assuming the switch already learned all MAC addresses, which hosts receive the frame on their NIC?</p><p><img alt="lan" src="${uLan}" /></p>`,
    options_A: 'Only H4',
    options_B: 'H2, H3, H4, and H5',
    options_C: 'All hosts H1–H5',
    options_D: 'Only H1 and H4',
    correct_option: 'A',
    solution: '',
    solutiontext:
      '<p><strong>Reasoning:</strong> A learning switch forwards a known unicast only out the port toward the destination MAC. Other hosts on different ports do not receive a copy.</p><p><strong>Answer:</strong> Option A (Only H4).</p>',
  }),
  row({
    chapter: 'transport-layer-protocol',
    topic: 'TCP flow and congestion control',
    difficulty: 'medium',
    questionImage: null,
    questionCode: `// Conceptual TCP sender (slow start)
cwnd = 1 * MSS; // initially
ssthresh = 64 * MSS;
onACK() {
  if (cwnd < ssthresh) cwnd += 1 * MSS; // slow start
  else cwnd += MSS * (MSS / cwnd);     // congestion avoidance
}`,
    question:
      '<p>Consider the TCP sender sketch below (classic Reno-style). Immediately after the handshake, the sender is in slow start with $\\mathrm{cwnd} = 1\\ \\mathrm{MSS}$. After <strong>$3$ successful RTTs with no loss</strong> (every segment ACKed), $\\mathrm{cwnd}$ equals how many $\\mathrm{MSS}$?</p>',
    options_A: '$3$',
    options_B: '$4$',
    options_C: '$8$',
    options_D: '$16$',
    correct_option: 'C',
    solution: '',
    solutiontext:
      '<p><strong>Reasoning:</strong> In slow start, cwnd roughly doubles each RTT while below ssthresh: $1 \\rightarrow 2 \\rightarrow 4 \\rightarrow 8\\ \\mathrm{MSS}$ after $3$ RTTs (still $< 64$).</p><p><strong>Answer:</strong> Option C ($8$).</p>',
  }),
  row({
    chapter: 'network-layer-protocol',
    topic: 'IPv4 CIDR fragmentation NAT',
    difficulty: 'easy',
    questionImage: uTopo,
    question: `<p>In the figure, Host A and Host B are in different $/24$ subnets connected by R1. Which statement is true?</p><p><img alt="topology" src="${uTopo}" /></p>`,
    options_A: 'A and B can communicate using link-layer forwarding only (no IP routing)',
    options_B: 'R1 must rewrite the destination IP of every packet from A to B',
    options_C: 'Packets from A to B are routed at the network layer via R1',
    options_D: 'Host B must use NAT to reply to Host A',
    correct_option: 'C',
    solution: '',
    solutiontext:
      '<p><strong>Reasoning:</strong> Different IP subnets cannot be bridged by pure L2 forwarding; R1 routes at L3. Basic IP routing does not rewrite destination IPs (that is NAT).</p><p><strong>Answer:</strong> Option C.</p>',
  }),
];

const { data: imgData, error: imgErr } = await supabase
  .from('examtracker')
  .insert(imageQs)
  .select('_id');
if (imgErr) {
  console.error(imgErr.message);
  process.exit(1);
}

const { count } = await supabase
  .from('examtracker')
  .select('_id', { count: 'exact', head: true })
  .eq('verification_status', 'unpublished_draft')
  .eq('subject', 'computer-networks');

const { data: sample } = await supabase
  .from('examtracker')
  .select('year,topic,question,solution,solutiontext')
  .eq('verification_status', 'unpublished_draft')
  .eq('subject', 'computer-networks')
  .limit(3);

console.log(
  JSON.stringify(
    {
      yearLabel: GENERATED_YEAR_LABEL,
      totalDrafts: count,
      imageInserted: imgData.length,
      sample: (sample || []).map((r) => ({
        year: r.year,
        topic: r.topic,
        solutionEmpty: !String(r.solution || '').trim(),
        solutiontextPreview: String(r.solutiontext || '')
          .replace(/<[^>]+>/g, ' ')
          .replace(/\s+/g, ' ')
          .trim()
          .slice(0, 160),
      })),
    },
    null,
    2
  )
);
